import{z as i,x as A,o as E,c as d,q as o,j as n,D as s,d as t,s as B,S as l,b as e}from"./chunks/framework.C8m1ZpeB.js";const D=JSON.parse('{"title":"性能计数器 PMU","description":"","frontmatter":{"title":"性能计数器 PMU","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/pmu-counters.md","filePath":"cs/pmu-counters.md","lastUpdated":1791063341000}'),p={name:"cs/pmu-counters.md"};function c(C,a,m,P,u,h){const r=A("Mermaid");return E(),d("div",null,[a[2]||(a[2]=o('<h1 id="性能计数器-pmu" tabindex="-1">性能计数器 PMU <a class="header-anchor" href="#性能计数器-pmu" aria-label="Permalink to &quot;性能计数器 PMU&quot;">​</a></h1><div class="epigraph"><p>把 CPI 拆成：周期、指令、缺失、误预测、停顿原因；计数器在核里，采样或累计，读的是这台机器上这个二进制，不是 SPEC 几何平均。</p><footer>—— 据 Intel SDM 对 PEBS/PMU 的描述；Hennessy and Patterson, CA:AQA 整理</footer></div><p><a href="/cs/spec-benchmark-pitfalls">上一课</a> 警告总分。设计者与调优者需要把 <a href="/cs/cpi-amdahl">CPI 公式</a> 的每一项变成可观测事件。本课不重讲 SPEC 规则。缺口是 <strong>PMU：硬件事件、如何对应到本课序里的结构（IQ、LSQ、预取、NoC）。</strong></p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>「程序慢」可能是 <a href="/cs/tage-predictor">TAGE</a> 误预测、LLC miss、<a href="/cs/false-sharing">伪共享</a>、fence 过多。没有计数器就只能猜。缺口不是 gem5 全系统模拟（下一课），而是<strong>片上已经埋的计数器：固定事件 + 可编程事件，溢出中断做采样。</strong></p><p><span class="marginnote">Intel 的 architectural 事件较稳；微结构事件随代际改名。ARM SPE、RISC-V 的 HPM 是同一层。本课讲机制，不绑定某一 <code>perf</code> 子命令教程。</span></p><p><span class="marginnote">CPI 就是每条指令平均花的周期数（Cycles Per Instruction）。PMU 可以类比分项油耗仪表：总里程（墙钟时间）相同时，它告诉你是空调（访存等待）费油还是急刹车（误预测）费油——没有它，你只知道「这箱油跑得短」。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>累计：一段时间读 <code>cycles</code>、<code>instructions</code>、<code>cache-misses</code>、<code>branch-misses</code>。采样：每 N 事件记 IP，找热点。点名到结构：L1D miss、L2 miss、DTLB miss、资源停顿（ROB 满、IQ 满）、预取有用/无用（若实现提供）。多核：按核、按 cgroup 看，对照 <a href="/cs/cache-partition-qos">分区</a>。</p>',9)),(E(),n(l,null,{default:s(()=>[B(r,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20EVT%5B%22%E7%A1%AC%E4%BB%B6%E4%BA%8B%E4%BB%B6%22%5D%20--%3E%20CTR%5B%22%E5%8F%AF%E7%BC%96%E7%A8%8B%E8%AE%A1%E6%95%B0%E5%99%A8%22%5D%0A%20%20CTR%20--%3E%20SAMP%5B%22%E6%BA%A2%E5%87%BA%E9%87%87%E6%A0%B7%20IP%22%5D%0A%20%20CTR%20--%3E%20CPI%5B%22%E6%8B%86%20CPI%20%E5%90%84%E9%A1%B9%22%5D%0A"})]),fallback:s(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("h2",{id:"机制",tabindex:"-1"},[t("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=e("p",null,"计数不是完美：超线程争用、乱序导致「事件归属哪条指令」模糊、PEBS 有偏。但仍比只看墙钟有用。安全：PMU 也是侧信道的时钟源，后课 Spectre 只要求知道「时序可测」，本课不讲如何测缓存。",-1)),a[5]||(a[5]=e("p",null,"自上而下（top-down）剖析把周期分成前端饥饿、后端、退休、坏推测四类，正好对应本课序的前端带宽、IQ/LSQ、ROB 头、误预测。先看大类再下钻事件，避免对着两百个计数器盲调。",-1)),a[6]||(a[6]=e("p",null,"五亿个周期被花在哪里？top-down 先按四大类分账。",-1)),(E(),n(l,null,{default:s(()=>[B(r,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20CYC%5B%22%E6%80%BB%E5%91%A8%E6%9C%9F%22%5D%20--%3E%20RET%5B%22%E9%80%80%E4%BC%91%EF%BC%9A%E7%9C%9F%E5%9C%A8%E6%8E%A8%E8%BF%9B%22%5D%0A%20%20CYC%20--%3E%20BAD%5B%22%E5%9D%8F%E6%8E%A8%E6%B5%8B%EF%BC%9A%E9%A2%84%E6%B5%8B%E9%94%99%EF%BC%8C%E7%99%BD%E5%81%9A%22%5D%0A%20%20CYC%20--%3E%20FE%5B%22%E5%89%8D%E7%AB%AF%E9%A5%A5%E9%A5%BF%EF%BC%9A%E5%8F%96%E6%8C%87%E4%BE%9B%E4%B8%8D%E4%B8%8A%22%5D%0A%20%20CYC%20--%3E%20BE%5B%22%E5%90%8E%E7%AB%AF%E5%8F%97%E9%99%90%EF%BC%9A%E8%AE%BF%E5%AD%98%E6%88%96%E8%B5%84%E6%BA%90%E5%A0%B5%22%5D%0A%20%20FE%20--%3E%20F1%5B%22%E4%B8%8B%E9%92%BB%EF%BC%9A%E5%88%86%E6%94%AF%E8%AF%AF%E9%A2%84%E6%B5%8B%E3%80%81%E6%8C%87%E4%BB%A4%E7%BC%93%E5%AD%98%E7%BC%BA%E5%A4%B1%22%5D%0A%20%20BE%20--%3E%20F2%5B%22%E4%B8%8B%E9%92%BB%EF%BC%9ALLC%20%E7%BC%BA%E5%A4%B1%E3%80%81DTLB%E3%80%81ROB%20%E6%BB%A1%22%5D%0A"})]),fallback:s(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=o('<p><span class="marginnote">数字实例：测得 10 亿条指令用了 5 亿周期，CPI=0.5；若 branch-misses 计数 1000 万、每次误预测罚约 15 个周期，坏推测就吃掉约 1.5 亿周期，占三成。优化目标立刻从「到处找」缩到「分支」这一项。</span></p><p><span class="marginnote">常见误区：把采样热点当成精确账本。乱序执行让「这个周期算谁的」本身模糊，PEBS 记的指令地址有偏，超线程还把同核两条线程的周期搅在一起。计数器是缩小范围的方向盘，不是财务报表。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不保证所有停顿原因都有架构级事件。gem5 下一课在模拟里把这些事件变得「可完美计数」，但有速度误差。Roofline 用带宽与 FLOP 计数画图，常从 PMU 或剖析器来。</p><p>后课默认：优化先看 PMU 拆项。算术强度与两堵墙用 Roofline 画。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>PMU 把 CPI 拆成可观测事件，针对本机本程序。</li><li>归属与超线程会引入噪声。</li><li>Roofline 把带宽墙与计算墙画在一张图上，下一课。</li><li>出处：Intel SDM；Hennessy and Patterson, <em>CA:AQA</em>。</li></ul>',7))])}const F=i(p,[["render",c]]);export{D as __pageData,F as default};
